function forward<O extends object>(names: readonly string[], owner: () => O): void {
	for (const n of names) {
		Object.defineProperty(G, n, {
			get: () => (owner() as Record<string, unknown>)[n],
			set: (v) => {
				(owner() as Record<string, unknown>)[n] = v;
			},
			enumerable: true,
			configurable: true
		});
	}
}
