/**
 * Back to program-start values (tests): the variables G stores, and the
 * input layer's. Arrays are replaced by new ones. Objects bound by runtime.ts
 * keep following G.
 */
export function resetGameState(): void {
	Object.assign(G, initial());
	resetState();
}
